 if err "'!= nil { t.Fatal(err) }
 defer read.Close()
 write, err := sql.Open(Driver, path)
 if err != nil { t.Fatal(err) }
 defer write.Close()
 database := &db{readDB:read, writeDB:write}
 ctx := context.Background()
 if _, err := write.Exec("CREATE TABLE items (value TEXT); INSERT INTO items VALUES ('"'before')\"); err "'!= nil { t.Fatal(err) }
 first, err := database.Backup(ctx)
 if err != nil { t.Fatal(err) }
 if _, err := os.Stat(first); err != nil { t.Fatal(err) }
 if _, err := write.Exec("UPDATE items SET value='"'after'\"); err "'!= nil { t.Fatal(err) }
 second, err := database.Backup(ctx)
 if err != nil { t.Fatal(err) }
 if first == second { t.Fatal("backup paths collided") }
 removed, err := database.Prune(ctx)
 if err != nil || removed != 1 { t.Fatalf("pruned %d: %v", removed, err) }
 if _, err := os.Stat(first); !os.IsNotExist(err) { t.Fatalf("old backup remains: %v", err) }
 if err := database.Restore(ctx, second); err != nil { t.Fatal(err) }
 var value string
